#include "qs_route_probe.h"
#include "qs_game.h"
#include <stdio.h>

/* This independent NRO-side witness uses the same QsInput steering
 * strategy as stage 87's native continuous-route regression.
 * Recorded game state is generated by qs_step, not host reconstruction. */
static int emit(FILE *f, unsigned seq, const char *event, int tick,
                const QsGame *g, int detail) {
    return fprintf(f,"%u,%s,%d,%d,%d,%d,%d,qs_step_simulated_inputs\n",
                   seq,event,tick,g->city_attempt_frames,
                   (int)(g->hero.x*1000.0f),
                   (int)(g->hero.y*1000.0f),detail) > 0 &&
           fflush(f)==0;
}
int qs_route_probe_write(FILE *stream) {
    QsGame g;
    unsigned seq=0;
    int pit_hold=0,roof_hold=0,crate_fired=0;
    int checkpoint=0,crate_broken=0,spring=0,heart=0,ledge=0;
    int t,hit;
    if(!stream) return 0;
    if(fputs("seq,event,tick,attempt,x_milli,y_milli,detail,source\n",stream)<0)
        return 0;
    qs_init(&g);
    g.physics_profile=QS_PHYSICS_REFERENCE_CITY;
    qs_begin_stage(&g,0);
    if(g.hero.x!=40 || g.hero.y!=188 || g.mode!=QS_STAGE ||
       !g.enemies[0].active || !g.enemies[1].active ||
       !g.enemies[2].active || !g.city_crate_active)
        return 0;
    if(!emit(stream,seq++,"SPAWN",0,&g,3))return 0;
    for(t=1;t<=1700;t++) {
        QsInput in={0};
        in.right=1;
        if(!pit_hold && !checkpoint && g.hero.x>=278 &&
           g.hero.x<320 && g.hero.grounded) {
            /* Only start the pit jump once. */
            if(!spring && !heart && g.city_attempt_frames<250)
                pit_hold=15;
        }
        if(!roof_hold && g.hero.x>=394 && g.hero.x<=425 &&
           g.hero.grounded && g.city_attempt_frames<400)
            roof_hold=15;
        if(pit_hold>0){in.jump=1;--pit_hold;}
        else if(roof_hold>0){in.jump=1;--roof_hold;}
        if(!crate_fired && g.city_checkpoint_active &&
           g.hero.x>=902 && g.hero.x<940 &&
           g.city_crate_active) {
            in.fire=1;crate_fired=1;
            if(!emit(stream,seq++,"CRATE_FIRE",t,&g,1))return 0;
        }
        if(spring && !ledge){
            in.right=0;
            if(!heart && g.hero.x<QS_CITY_AIR_REWARD_X-1)in.right=1;
            if(heart && g.hero.x<QS_CITY_SKY_LEDGE_X+6)in.right=1;
        }
        if(ledge)in.right=1;
        hit=g.city_crate_active;
        qs_step(&g,in);
        if(g.city_checkpoint_active && !checkpoint){
            checkpoint=t;
            if(!emit(stream,seq++,"CHECKPOINT",t,&g,
                     g.city_checkpoint_split_frames))return 0;
        }
        if(hit && !g.city_crate_active && !crate_broken){
            crate_broken=t;
            if(!emit(stream,seq++,"CRATE_BROKEN",t,&g,0))return 0;
        }
        if(!spring &&
           g.city_spring_flash_frames==QS_CITY_SPRING_FLASH_TICKS){
            spring=t;
            if(!emit(stream,seq++,"SPRING",t,&g,
                     g.city_spring_flash_frames))return 0;
        }
        if(!heart && g.city_air_reward_collected){
            heart=t;
            if(!emit(stream,seq++,"HEART",t,&g,
                     g.city_air_reward_collected))return 0;
        }
        if(heart && !ledge && g.hero.grounded &&
           g.hero.y==QS_CITY_SKY_LEDGE_TOP-20){
            ledge=t;
            if(!emit(stream,seq++,"LEDGE",t,&g,1))return 0;
        }
        if(g.mode==QS_MAP){
            if(!checkpoint || !crate_fired || !crate_broken ||
               !spring || !heart || !ledge || !g.cleared[0] ||
               !(checkpoint<crate_broken && crate_broken<spring &&
                 spring<heart && heart<ledge && ledge<t) ||
               g.city_best_clear_frames<=0)return 0;
            if(!emit(stream,seq++,"CLEAR",t,&g,
                     g.city_best_clear_frames))return 0;
            qs_step(&g,(QsInput){0});
            QsInput reenter={0};
            reenter.select=1;reenter.dash=1;
            qs_step(&g,reenter);
            if(g.mode!=QS_STAGE || g.hero.x!=40 ||
               g.city_attempt_frames!=0 || g.city_crate_active!=1 ||
               g.city_checkpoint_active!=0 ||
               g.city_air_reward_collected!=0 ||
               g.city_best_clear_frames<=0)return 0;
            if(!emit(stream,seq++,"REENTRY",t,&g,
                     g.city_best_clear_frames))return 0;
            return 1;
        }
    }
    return 0;
}
